import math

def to_simple_exponential_notation(x_str):
    x = float(x_str)
    if x == 0:
        return "0"

    # Calculate the exponent b
    b = math.floor(math.log10(abs(x)))

    # Calculate the mantissa a
    a = x / (10 ** b)

    # Format the mantissa a
    if a.is_integer():
        a = int(a)
    else:
        a = f"{a:.12g}"

    # Format the result
    if b == 0:
        return str(a)
    else:
        return f"{a}E{b}"

